import json, zipfile, os, re, shutil
from xml.sax.saxutils import escape

# --- Paths (adjusted after inspection) ---
TEMPLATE = '/root/safety_audit_template.hwpx'
OVERVIEW = '/root/audit_overview.json'
ACTIONS  = '/root/corrective_actions.json'
OUTPUT   = '/root/safety_audit_brief_final.hwpx'
WORK     = '/tmp/hwpx_build'

# --- Load JSON ---
with open(OVERVIEW, encoding='utf-8') as f:
    overview_raw = json.load(f)

# audit_overview.json is {"summary": {...}}
overview = overview_raw.get('summary', overview_raw)

with open(ACTIONS, encoding='utf-8') as f:
    actions_raw = json.load(f)

# corrective_actions.json is {"immediate_actions": [..]}
actions_list = actions_raw.get('immediate_actions', actions_raw)
if not isinstance(actions_list, list):
    raise TypeError('corrective_actions.json must contain a list under immediate_actions')

# --- Severity mapping ---
SEVERITY = {'High': '즉시조치', 'Medium': '계획보완', 'Low': '모니터링'}

# --- Helpers ---
def xml_escape(val: object) -> str:
    return escape('' if val is None else str(val))

def merge_adjacent_hp_t_within_runs(xml_text: str) -> str:
    """If placeholders are split across adjacent <hp:t> nodes, merge them into one.

    Only merges when a <hp:run> contains only <hp:t> elements (and whitespace).
    """
    run_re = re.compile(r'(<hp:run\b[^>]*>)(.*?)(</hp:run>)', re.DOTALL)

    def _merge_one(m: re.Match) -> str:
        open_tag, body, close_tag = m.group(1), m.group(2), m.group(3)

        # Quick reject: no adjacent <hp:t> => nothing to merge
        if body.count('<hp:t>') <= 1:
            return m.group(0)

        # Only safe to merge if body is composed solely of <hp:t>...</hp:t> nodes
        only_t_re = re.compile(r'^\s*(?:<hp:t>.*?</hp:t>\s*)+$', re.DOTALL)
        if not only_t_re.match(body):
            return m.group(0)

        parts = re.findall(r'<hp:t>(.*?)</hp:t>', body, flags=re.DOTALL)
        if not parts:
            return m.group(0)

        merged = ''.join(parts)
        return f'{open_tag}<hp:t>{merged}</hp:t>{close_tag}'

    return run_re.sub(_merge_one, xml_text)

# --- Build replacement map from overview ---
replacements: dict[str, str] = {}

# Risk tier key in this template/JSON is "위험등급"
risk_key = '위험등급'
risk_val = str(overview.get(risk_key, ''))
if risk_val in SEVERITY:
    risk_val_formatted = f'{risk_val} ({SEVERITY[risk_val]})'
else:
    risk_val_formatted = risk_val

for key, val in overview.items():
    if key == risk_key:
        replacements['{{' + key + '}}'] = xml_escape(risk_val_formatted)
    else:
        replacements['{{' + key + '}}'] = xml_escape(val)

# Corrective actions placeholders: {{조치1}}, {{조치2}}, {{조치3}}
for idx in range(1, 4):
    val = actions_list[idx - 1] if idx - 1 < len(actions_list) else ''
    replacements[f'{{{{조치{idx}}}}}'] = xml_escape(val)

# --- Unpack template ---
if os.path.exists(WORK):
    shutil.rmtree(WORK)
os.makedirs(WORK, exist_ok=True)

with zipfile.ZipFile(TEMPLATE, 'r') as zf:
    zf.extractall(WORK)

# --- Find all XML files that may contain placeholders ---
xml_files: list[str] = []
for root, dirs, files in os.walk(WORK):
    for fn in files:
        if fn.endswith('.xml'):
            xml_files.append(os.path.join(root, fn))

had_remaining = False

# --- Process each XML file ---
for xml_path in xml_files:
    with open(xml_path, 'r', encoding='utf-8') as f:
        content = f.read()

    original = content

    # 0) Merge adjacent <hp:t> within runs (handles split placeholders)
    content = merge_adjacent_hp_t_within_runs(content)

    # 1) Replace all placeholders
    for placeholder, value in replacements.items():
        content = content.replace(placeholder, value)

    # 2) Risk tier: ensure any remaining standalone tier words are formatted
    if risk_val in SEVERITY:
        formatted = f'{risk_val} ({SEVERITY[risk_val]})'
        content = re.sub(re.escape(risk_val) + r'(?!\s*\()', formatted, content)

    # 3) Rewrite inspection date from YYYY-MM-DD to YYYY.MM.DD everywhere
    content = re.sub(r'(\d{4})-(\d{2})-(\d{2})', r'\1.\2.\3', content)

    # 4) Remove layout cache elements to prevent stale rendering
    #    Template uses <hp:linesegarray> (lowercase), but be robust to <hp:lineSegArray> too.
    content = re.sub(r'<hp:(?:lineSegArray|linesegarray)[^>]*>.*?</hp:(?:lineSegArray|linesegarray)>', '', content, flags=re.DOTALL)
    content = re.sub(r'<hp:(?:lineSegArray|linesegarray)[^/]*/>', '', content)

    # 5) Verify no {{...}} placeholders remain
    remaining = re.findall(r'\{\{.*?\}\}', content)
    if remaining:
        had_remaining = True
        print(f'ERROR: remaining placeholders in {xml_path}: {remaining}')

    if content != original:
        with open(xml_path, 'w', encoding='utf-8') as f:
            f.write(content)
        print(f'Updated: {xml_path}')

if had_remaining:
    raise SystemExit('Aborting: one or more placeholders were not replaced.')

# --- Repack as .hwpx (ZIP) preserving structure ---
with zipfile.ZipFile(OUTPUT, 'w', zipfile.ZIP_DEFLATED) as zf:
    for root, dirs, files in os.walk(WORK):
        for fn in files:
            full = os.path.join(root, fn)
            arcname = os.path.relpath(full, WORK)
            zf.write(full, arcname)

print(f'Output written to {OUTPUT}')

